sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_scale;
uniform float amzp_angle;
uniform float2 amzp_position;
uniform float2 amzp_stretch;
uniform float amzp_alpha;
uniform float amzp_hardness;
uniform float amzp_blendMode;
uniform float amzp_alphaComp;
uniform float amzp_gradType;
uniform float amzp_progress;
layout(color) uniform half4 amzp_color1;
layout(color) uniform half4 amzp_color2;
layout(color) uniform half4 amzp_color3;
uniform float amzp_useMid;
uniform float amzp_pos1;
uniform float amzp_posMid;
uniform float amzp_pos3;
uniform float amzp_smoothG;
uniform float amzp_mixMode;
uniform float amzp_steps;
uniform float amzp_repMode;
uniform float amzp_dither;
uniform float amzp_overdrawOn;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float2 nmRot(float2 q, float a) { float c = cos(a), s = sin(a); return float2(c * q.x - s * q.y, s * q.x + c * q.y); }
    float2 nmStd(float2 p, float pxk) {
        float z = max(amzp_scale * 2.0, 0.002);
        p -= amzp_position * pxk;
        p = nmRot(p, -radians(amzp_angle));
        return p / (z * max(amzp_stretch, float2(0.01)));
    }
    float2 nmStdUp(float2 d, float pxk) { float2 p = nmStd(float2(d.x, -d.y), pxk); return float2(p.x, -p.y); }
    float4 nmBlend(float4 tex, float4 fx) {
        float4 f = clamp(fx * amzp_hardness, 0.0, 1.0) * clamp(amzp_alpha, 0.0, 1.0);
        float4 b = tex * clamp(amzp_alphaComp, 0.0, 1.0);
        if (int(amzp_blendMode) == 0) return f;
        if (int(amzp_blendMode) == 1) return float4(b.rgb * (f.rgb + (1.0 - f.a)), b.a);
        if (int(amzp_blendMode) == 2) return float4(b.rgb + f.rgb - b.rgb * f.rgb, b.a + f.a - b.a * f.a);
        return f + b * (1.0 - f.a);
    }
    float4 layerAt(float2 uv) { return (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float TT() { return amzp_progress; }
    float3 toLin(float3 c) { return pow(max(c, 0.0), float3(2.2)); }
    float3 toSrgb(float3 c) { return pow(max(c, 0.0), float3(1.0 / 2.2)); }
    float3 oklab(float3 c) {
        c = toLin(c);
        float l = 0.4122214708 * c.r + 0.5363325363 * c.g + 0.0514459929 * c.b;
        float m = 0.2119034982 * c.r + 0.6806995451 * c.g + 0.1073969566 * c.b;
        float s = 0.0883024619 * c.r + 0.2817188376 * c.g + 0.6299787005 * c.b;
        l = pow(max(l, 0.0), 1.0 / 3.0); m = pow(max(m, 0.0), 1.0 / 3.0); s = pow(max(s, 0.0), 1.0 / 3.0);
        return float3(0.2104542553 * l + 0.7936177850 * m - 0.0040720468 * s,
                    1.9779984951 * l - 2.4285922050 * m + 0.4505937099 * s,
                    0.0259040371 * l + 0.7827717662 * m - 0.8086757660 * s);
    }
    float3 unOklab(float3 L) {
        float l = L.x + 0.3963377774 * L.y + 0.2158037573 * L.z;
        float m = L.x - 0.1055613458 * L.y - 0.0638541728 * L.z;
        float s = L.x - 0.0894841775 * L.y - 1.2914855480 * L.z;
        l = l * l * l; m = m * m * m; s = s * s * s;
        float3 c = float3(4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
                      -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
                      -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s);
        return clamp(toSrgb(c), 0.0, 1.0);
    }
    float4 mixC(float4 a, float4 b, float f) {
        float al = mix(a.a, b.a, f);
        float wb = al > 0.0001 ? f * b.a / al : f;
        if (a.a < 0.0001) wb = 1.0;
        if (b.a < 0.0001) wb = 0.0;
        float3 c = int(amzp_mixMode) == 1 ? unOklab(mix(oklab(a.rgb), oklab(b.rgb), wb)) : mix(a.rgb, b.rgb, wb);
        return float4(c, al);
    }
    float shapeF(float f) {
        f = clamp(f, 0.0, 1.0);
        float s = clamp(amzp_smoothG, 0.0, 1.0);
        float g = clamp((f - 0.5) / max(s, 0.001) + 0.5, 0.0, 1.0);
        return mix(g, f, s * s) ;
    }
    float4 ramp(float t) {
        float p1 = amzp_pos1, p3 = amzp_pos3;
        if (!(amzp_useMid>0.5)) {
            float f = (t - p1) / (abs(p3 - p1) < 1e-4 ? 1e-4 : (p3 - p1));
            return mixC(amzp_color1, amzp_color3, shapeF(f));
        }
        float pm = amzp_posMid;
        if (t <= pm) {
            float f = (t - p1) / (abs(pm - p1) < 1e-4 ? 1e-4 : (pm - p1));
            return mixC(amzp_color1, amzp_color2, shapeF(f));
        }
        float f = (t - pm) / (abs(p3 - pm) < 1e-4 ? 1e-4 : (p3 - pm));
        return mixC(amzp_color2, amzp_color3, shapeF(f));
    }
    float lum(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }
    float3 setLum(float3 c, float l) {
        c += l - lum(c);
        float L = lum(c), n = min(c.r, min(c.g, c.b)), x = max(c.r, max(c.g, c.b));
        if (n < 0.0) c = L + (c - L) * L / max(L - n, 1e-5);
        if (x > 1.0) c = L + (c - L) * (1.0 - L) / max(x - L, 1e-5);
        return c;
    }
    void amzRender() {
        float2 W = layer;
        float2 uv = amzLayerNorm();
        float4 orig = layerAt(uv);
        float2 p = nmStdUp((uv - 0.5) * W, pxs());
        float t;
        if (int(amzp_gradType) == 0) t = p.x / max(W.x, 1.0) + 0.5;
        else if (int(amzp_gradType) == 1) t = length(p) / max(0.5 * length(W), 1.0);
        else if (int(amzp_gradType) == 2) t = fract(atan(p.y, p.x) / 6.28318531 + 1.0);
        else if (int(amzp_gradType) == 3) t = abs(p.x) / max(W.x, 1.0) + abs(p.y) / max(W.y, 1.0);
        else if (int(amzp_gradType) == 4) t = abs(p.x) / max(0.5 * W.x, 1.0);
        else t = max(abs(p.x) / max(0.5 * W.x, 1.0), abs(p.y) / max(0.5 * W.y, 1.0));
        t += TT();
        if (int(amzp_repMode) == 1) t = fract(t);
        else if (int(amzp_repMode) == 2) t = 1.0 - abs(1.0 - mod(t, 2.0));
        if (amzp_steps >= 2.0) {
            float n = floor(amzp_steps + 0.5);
            t = floor(clamp(t, 0.0, 0.9999) * n) / (n - 1.0);
        }
        float4 g = ramp(t);
        if ((amzp_dither>0.5)) g.rgb += (fract(sin(dot(amzScreenNorm() * screen.zw, float2(12.9898, 78.233))) * 43758.5453) - 0.5) / 255.0;
        g.rgb = clamp(g.rgb, 0.0, 1.0);
        float4 fx = float4(g.rgb * g.a, g.a);
        float4 R;
        if (int(amzp_blendMode) < 4) R = nmBlend(orig, fx);
        else {
            float4 f = clamp(fx * amzp_hardness, 0.0, 1.0) * clamp(amzp_alpha, 0.0, 1.0);
            float ga = f.a;
            float3 gc = ga > 0.0001 ? f.rgb / ga : float3(0.0);
            float4 o = orig * clamp(amzp_alphaComp, 0.0, 1.0);
            float3 oc = o.a > 0.0001 ? o.rgb / o.a : float3(0.0);
            if (int(amzp_blendMode) == 7) R = float4(min(o.rgb + gc * ga * o.a, float3(o.a)), o.a);
            else {
                float3 b;
                if (int(amzp_blendMode) == 4) b = mix(2.0 * oc * gc, 1.0 - 2.0 * (1.0 - oc) * (1.0 - gc), step(0.5, oc));
                else if (int(amzp_blendMode) == 5) b = mix(2.0 * oc * gc + oc * oc * (1.0 - 2.0 * gc), sqrt(oc) * (2.0 * gc - 1.0) + 2.0 * oc * (1.0 - gc), step(0.5, gc));
                else b = setLum(gc, lum(oc));
                R = float4(mix(oc, clamp(b, 0.0, 1.0), ga) * o.a, o.a);
            }
        }
        amzOutput = R;
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
